(function(E){ const x = E["exam-09"] = E["exam-09"] || {units:{}}; (x.units = x.units || {})["x09-l4"] = {"id":"x09-l4","patterns":["L4-history","PARA-signpost","TR-plural","TR-limit","TR-paraphrase"],"title":{"en":"Listening Part 4: a talk on history","tr":"Listening Part 4: tarih üzerine bir konuşma","fa":"Listening Part 4: سخنرانی درباره‌ی تاریخ"},"objective":{"en":"In this lesson you will learn to follow a talk about an ancient object from discovery to display, and complete ten notes with the exact word you hear.","tr":"Bu derste eski bir nesneyi bulunuşundan sergilenmesine kadar anlatan bir konuşmayı takip etmeyi ve on notu duyduğun kelimenin tam aynısıyla tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری سخنرانی‌ای را درباره‌ی یک شیء باستانی، از پیدا شدن تا نمایش، دنبال کنی و ده یادداشت را دقیقاً با همان کلمه‌ای که می‌شنوی کامل کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 4: a talk on history","tr":"Listening Part 4: tarih üzerine bir konuşma","fa":"Listening Part 4: سخنرانی درباره‌ی تاریخ"},"objective":{"en":"In this lesson you will learn to follow a talk about an ancient object from discovery to display, and complete ten notes with the exact word you hear.","tr":"Bu derste eski bir nesneyi bulunuşundan sergilenmesine kadar anlatan bir konuşmayı takip etmeyi ve on notu duyduğun kelimenin tam aynısıyla tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری سخنرانی‌ای را درباره‌ی یک شیء باستانی، از پیدا شدن تا نمایش، دنبال کنی و ده یادداشت را دقیقاً با همان کلمه‌ای که می‌شنوی کامل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"1"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word","tr":"1 kelime","fa":"۱ کلمه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: an ancient boat","tr":"Bu sınav: eski bir tekne","fa":"این آزمون: یک قایق باستانی"},"intro":{"en":"History and culture are the second largest group of Part 4 topics. Talks about a find or an old technique move through a fixed story: discovery, description, purpose, survival, what happens now.","tr":"Tarih ve kültür, Part 4 konularının ikinci büyük grubudur. Bir buluntu ya da eski bir teknik hakkındaki konuşmalar sabit bir hikâyeyi izler: bulunuş, tanım, amaç, günümüze kalış, şimdi ne olduğu.","fa":"تاریخ و فرهنگ دومین گروه بزرگ موضوع‌های Part 4 است. سخنرانی‌های مربوط به یک یافته یا یک فن قدیمی داستانی ثابت را دنبال می‌کنند: پیدا شدن، توصیف، کاربرد، سالم ماندن، و وضعیت امروز."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x09-l4-ctx","exam":true,"patterns":["L4-history","PARA-signpost"],"often":{"pattern":"L4-history","n":13,"of":40,"label":{"en":"Comes up often in the real exam: 13 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 13’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۳ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A talk about an archaeological find","tr":"Bir arkeolojik buluntu hakkında bir konuşma","fa":"سخنرانی درباره‌ی یک یافته‌ی باستان‌شناسی"},"asks":{"en":"A museum specialist describes an ancient object: how it was found, what it is made of, how it was made, what it was used for, why it survived and how it has been conserved and displayed. The notes follow this order.","tr":"Bir müze uzmanı eski bir nesneyi anlatıyor: nasıl bulunduğunu, neyden yapıldığını, nasıl yapıldığını, ne için kullanıldığını, neden bugüne kadar kaldığını ve nasıl korunup sergilendiğini. Notlar bu sırayı izler.","fa":"یک متخصص موزه شیئی باستانی را توصیف می‌کند: چطور پیدا شد، از چه ساخته شده، چطور ساخته شد، برای چه استفاده می‌شد، چرا سالم ماند و چطور حفاظت و نمایش داده می‌شود. یادداشت‌ها همین ترتیب را دارند."},"fields":["Discovery","Material","Method of building","Use","Why it survived","Conservation and display"],"words":[{"a":"by accident","b":"by chance / nobody was looking for it","tr":"tesadüfen","fa":"تصادفی"},{"a":"made of","b":"built from / consists of","tr":"... yapılmış","fa":"ساخته‌شده از"},{"a":"joined","b":"sewn / tied / fixed together","tr":"birleştirilmiş","fa":"به هم وصل‌شده"},{"a":"cargo","b":"what it carried / goods","tr":"yük","fa":"بار"},{"a":"deliberately","b":"on purpose / not by accident","tr":"kasıtlı olarak","fa":"عمداً"},{"a":"preserved","b":"survived / kept in good condition","tr":"korunmuş","fa":"سالم مانده"},{"a":"rot","b":"decay / break down","tr":"çürümek","fa":"پوسیدن"},{"a":"waterlogged","b":"full of water / soaked","tr":"suya doymuş","fa":"آب‌گرفته"},{"a":"conservation","b":"treatment to stop damage","tr":"koruma, restorasyon","fa":"حفاظت و مرمت"},{"a":"soaked in","b":"kept in a tank of","tr":"... içinde bekletilmiş","fa":"خیسانده‌شده در"},{"a":"displayed","b":"shown / on view in a case","tr":"sergilenmiş","fa":"به نمایش گذاشته‌شده"},{"a":"a theory","b":"one explanation is / we think it may","tr":"bir kuram","fa":"یک نظریه"}],"traps":[{"en":"\"Most people imagine... In reality...\" The first idea is the common belief; the note needs the fact.","tr":"\"Çoğu kişi ... sanır. Gerçekte ...\" İlk fikir yaygın inanış; not gerçeği ister.","fa":"«بیشتر مردم تصور می‌کنند... در واقع...». ایده‌ی اول باور رایج است؛ یادداشت واقعیت را می‌خواهد."},{"en":"A word is already printed: \"___-dried\", \"planks of ___\". Write only the missing part.","tr":"Bir kelime zaten yazılı: \"___-dried\", \"planks of ___\". Yalnızca eksik kısmı yaz.","fa":"کلمه‌ای از قبل چاپ شده: «___-dried»، «planks of ___». فقط بخش جاافتاده را بنویس."},{"en":"Numbers are mentioned (metres, years), but a ONE WORD ONLY note never takes a number.","tr":"Sayılardan söz edilir (metre, yıl) ama ONE WORD ONLY notuna asla sayı yazılmaz.","fa":"از عدد حرف زده می‌شود (متر، سال)، اما در یادداشتِ ONE WORD ONLY هیچ‌وقت عدد نمی‌نویسی."}],"example":{"lines":[["Speaker","You might think the statue was carved from marble. It looks like it. In fact, it’s limestone, which was much easier to work."]],"item":"The statue · carved from ___","answer":"limestone","why":{"en":"Marble is what \"you might think\". \"In fact\" gives the material: limestone.","tr":"Mermer \"düşünebileceğin\" şey. \"In fact\" malzemeyi veriyor: kireçtaşı.","fa":"سنگ مرمر چیزی است که «شاید فکر کنی». «in fact» جنسش را می‌گوید: سنگ آهک."}}},{"id":"L4-history","ctx":["L4-history"],"title":{"en":"History and culture","tr":"Tarih ve kültür","fa":"تاریخ و فرهنگ"},"asks":{"en":"A lecturer tells the story of an object, a place, a craft or an idea: where it began, how it was made, who used it, how it changed and why it matters now.","tr":"Bir öğretim görevlisi bir nesnenin, bir yerin, bir zanaatın ya da bir fikrin hikâyesini anlatır: nerede başladığı, nasıl yapıldığı, kimin kullandığı, nasıl değiştiği ve bugün neden önemli olduğu.","fa":"یک سخنران داستان یک شیء، یک مکان، یک صنعت دستی یا یک ایده را تعریف می‌کند: از کجا شروع شد، چطور ساخته می‌شد، چه کسانی از آن استفاده می‌کردند، چطور تغییر کرد و چرا امروز مهم است."},"fields":["Origins","Materials","How it was made","Who used it","Changes over time","Reasons for decline","Interest today"],"words":[{"a":"origins","b":"where it began / it first appeared","tr":"kökenler","fa":"ریشه‌ها"},{"a":"ancient","b":"thousands of years old","tr":"antik","fa":"باستانی"},{"a":"craft","b":"made by hand / a skill","tr":"zanaat","fa":"صنعت دستی"},{"a":"materials","b":"what it was made from","tr":"malzemeler","fa":"مواد"},{"a":"merchants","b":"traders / people who sold goods","tr":"tüccarlar","fa":"بازرگانان"},{"a":"wealthy","b":"rich families","tr":"varlıklı","fa":"ثروتمند"},{"a":"status symbol","b":"a sign that you were important","tr":"statü sembolü","fa":"نشانه‌ی جایگاه اجتماعی"},{"a":"decline","b":"became less common / fell out of use","tr":"gerileme","fa":"افول"},{"a":"revival","b":"it became popular again","tr":"yeniden canlanma","fa":"احیا"},{"a":"settlers","b":"people who arrived and stayed","tr":"yerleşimciler","fa":"ساکنان تازه‌وارد"},{"a":"evidence","b":"what archaeologists found","tr":"kanıt","fa":"شواهد"},{"a":"ritual","b":"a ceremony / a custom","tr":"ritüel","fa":"آیین"},{"a":"manuscript","b":"a handwritten document","tr":"el yazması","fa":"نسخه‌ی خطی"}],"traps":[{"en":"Dates: \"the 1600s\" is the seventeenth century. Check which period the heading is about.","tr":"Tarihler: \"the 1600s\" on yedinci yüzyıldır. Başlığın hangi dönemi sorduğuna bak.","fa":"تاریخ‌ها: «the 1600s» یعنی قرن هفدهم. ببین عنوان درباره‌ی کدام دوره است."},{"en":"A popular belief is corrected: \"people often say it was invented in China; in fact the earliest examples come from...\".","tr":"Yaygın bir inanış düzeltilir: \"genelde Çin’de icat edildiği söylenir; aslında en eski örnekler ... gelir\".","fa":"یک باور رایج اصلاح می‌شود: «معمولاً می‌گویند در چین اختراع شد؛ در واقع قدیمی‌ترین نمونه‌ها از ... هستند»."}],"example":{"lines":[["Lecturer","People often assume pockets were always sewn into clothes."],["Lecturer","In fact, until the late 1600s, they were separate bags, tied around the waist under a skirt or a coat."]],"item":"Early pockets: separate ___ tied around the waist   (ONE WORD ONLY)","answer":"bags","why":{"en":"\"Sewn into clothes\" is the popular belief. \"In fact... separate bags\": write bags.","tr":"\"Kıyafete dikili\" yaygın inanış. \"In fact... separate bags\": bags yaz.","fa":"«دوخته‌شده در لباس» باور رایج است. «In fact... separate bags»: بنویس bags."}},"general":true,"patterns":["L4-history"],"often":{"pattern":"L4-history","n":13,"of":40,"label":{"en":"Comes up often in the real exam: 13 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 13’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۳ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"One talk, ten notes, no break","tr":"Bir konuşma, on not, ara yok","fa":"یک سخنرانی، ده یادداشت، بدون مکث"},"body":{"en":"Questions 31-40 are notes under five or six headings. Write ONE WORD ONLY. You have about 45 seconds to read, and then the talk plays without a pause. Answers come in order.","tr":"Soru 31-40, beş altı başlık altındaki notlardır. YALNIZCA BİR KELİME yaz. Okumak için yaklaşık 45 saniyen var, sonra konuşma hiç durmadan çalar. Cevaplar sırayla gelir.","fa":"سؤال‌های ۳۱ تا ۴۰ یادداشت‌هایی زیر پنج شش عنوان‌اند. فقط یک کلمه بنویس. حدود ۴۵ ثانیه برای خواندن داری و بعد سخنرانی بدون مکث پخش می‌شود. جواب‌ها به ترتیب می‌آیند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Read the headings and predict the story: found, made, used, survived, kept.","tr":"Başlıkları oku ve hikâyeyi tahmin et: bulundu, yapıldı, kullanıldı, kaldı, korundu.","fa":"عنوان‌ها را بخوان و داستان را حدس بزن: پیدا شد، ساخته شد، استفاده شد، ماند، نگه‌داری شد."},{"en":"Decide the word class for each gap: a material, a part, a verb in the passive, a quality.","tr":"Her boşluk için kelime türüne karar ver: bir malzeme, bir parça, edilgen bir fiil, bir özellik.","fa":"نوع کلمه‌ی هر جای خالی را مشخص کن: ماده، بخش، فعل مجهول، ویژگی."},{"en":"Follow signposts: \"Let me begin with\", \"So what was it for?\", \"Now, why did it survive?\", \"Finally\".","tr":"Geçiş ifadelerini izle: \"Let me begin with\", \"So what was it for?\", \"Now, why did it survive?\", \"Finally\".","fa":"نشانه‌ها را دنبال کن: «Let me begin with»، «So what was it for?»، «Now, why did it survive?»، «Finally»."},{"en":"Write the exact word, singular or plural, and never a number.","tr":"Kelimeyi tekil ya da çoğul, tam olarak yaz; asla sayı yazma.","fa":"کلمه را دقیقاً، مفرد یا جمع، بنویس و هیچ‌وقت عدد ننویس."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Belief first, fact second","tr":"Önce inanış, sonra gerçek","fa":"اول باور، بعد واقعیت"},"body":{"en":"History talks often correct a belief: \"Most people imagine..., but in reality...\", \"It wasn’t cut from a single trunk... Instead...\". The word after \"in reality\", \"in fact\" or \"instead\" is the one the note needs.","tr":"Tarih konuşmaları çoğu zaman bir inanışı düzeltir: \"Çoğu kişi ... sanır ama gerçekte...\", \"Tek bir gövdeden oyulmamıştı... Onun yerine...\". Notun istediği kelime \"in reality\", \"in fact\" ya da \"instead\"den sonra gelendir.","fa":"سخنرانی‌های تاریخی اغلب یک باور را اصلاح می‌کنند: «بیشتر مردم تصور می‌کنند...، اما در واقع...»، «از یک تنه کنده نشده بود... در عوض...». کلمه‌ای که یادداشت می‌خواهد بعد از «in reality»، «in fact» یا «instead» می‌آید."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One note, step by step","tr":"Bir not, adım adım","fa":"یک یادداشت، قدم به قدم"},"instruction":"Complete the notes below. Write ONE WORD ONLY for each answer.","item":"The coins · hidden inside a ___","lines":[["Speaker","The coins weren’t buried in a box, as we expected. Instead, they had been pushed inside a leather bag and hidden in a wall."]],"answer":"bag","walk":[{"en":"The gap needs a container: a noun after \"a\".","tr":"Boşluk bir kap istiyor: \"a\"dan sonra bir isim.","fa":"جای خالی یک ظرف می‌خواهد: اسمی بعد از «a»."},{"en":"\"A box\" is what they expected; \"instead\" brings the fact.","tr":"\"A box\" bekledikleri şey; \"instead\" gerçeği getiriyor.","fa":"«a box» چیزی است که انتظار داشتند؛ «instead» واقعیت را می‌آورد."},{"en":"\"Leather bag\" is two words; the noun the note needs is bag.","tr":"\"Leather bag\" iki kelime; notun istediği isim bag.","fa":"«leather bag» دو کلمه است؛ اسمی که یادداشت می‌خواهد bag است."}]},"quick":{"prompt":"Notes: \"The jar was used to store ___\" (ONE WORD ONLY). You hear: \"People assumed it held wine, but tests found traces of honey.\" What do you write?","options":["wine","honey","traces"],"correct":1,"why":{"en":"Wine is the assumption; the tests found honey.","tr":"Şarap varsayım; testler bal buldu.","fa":"شراب یک تصور است؛ آزمایش‌ها عسل پیدا کردند."}},"remember":{"en":"Predict the story from the headings, wait for \"in fact\" or \"instead\", and write one exact word.","tr":"Başlıklardan hikâyeyi tahmin et, \"in fact\" ya da \"instead\"i bekle ve tam bir kelime yaz.","fa":"داستان را از عنوان‌ها حدس بزن، منتظر «in fact» یا «instead» بمان و یک کلمه‌ی دقیق بنویس."},"type":"explain","id":"c-x09-l4-e","course":"ielts-exams","exam":"exam-09","unit":"x09-l4"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 4","title":{"en":"A boat from the Bronze Age","tr":"Tunç Çağı’ndan bir tekne","fa":"قایقی از عصر مفرغ"},"timed":8,"ctx":["L4-history"],"script":[{"who":"Speaker","line":"Good afternoon, and welcome to this month's museum lecture. My subject today is a boat that is more than three thousand years old, and that now sits in a glass case in the gallery downstairs. I'll tell you how it was found, how it was built, what it may have been used for, and how we've managed to keep it from falling apart."},{"who":"Speaker","line":"Let me begin with the discovery. Most people imagine archaeologists finding things like this after years of careful searching. In reality, it was found by accident. Six years ago, engineers were laying a new pipeline beneath the bed of the river, about two kilometres from the town centre, and their machine struck something wooden at a depth of almost six metres. Work stopped immediately, and the museum was called in. Within a day, a temporary dam had been built around the site so that our team could work in the dry."},{"who":"Speaker","line":"What we found was the lower half of a large boat, around nine metres long. It wasn't cut out of a single tree trunk, as many early boats were. Instead, it was made of planks of oak, some of them over half a metre wide, which tells us that the builders had access to very large, old trees. Tree-ring dating shows that the trees were felled within a few years of each other, so the boat was probably built in one go rather than repaired over generations."},{"who":"Speaker","line":"The most remarkable thing about the boat is how it was held together. There are no nails or metal fixings at all. The planks were sewn together, rather like clothing, using thin, twisted stems of yew. The builders cut holes along the edges of each plank, pulled the yew through and tied it tightly. To keep the water out, they pressed moss into the joints and covered it with thin strips of wood. It must have taken a team of skilled people many weeks."},{"who":"Speaker","line":"So what was the boat for? Its flat bottom suggests it was used on rivers and in sheltered coastal waters rather than on the open sea, although some of my colleagues disagree with that. We do have one clue about its cargo. When we cleaned the inside of the hull, we found a small number of charred seeds caught in the cracks, and these turned out to be barley. That doesn't prove the boat was carrying grain on its final journey, of course, but it suggests it was used to move food between settlements."},{"who":"Speaker","line":"There's another puzzle. One end of the boat was missing, and the marks on the wood show that this wasn't caused by rot or by the river. It had been deliberately damaged, with tools, before the boat was left in the water. Why would anyone do that to such a valuable object? One theory is that it was part of a ceremony to mark the end of the boat's working life, but at the moment we simply don't know. I hope that further work on similar finds will help us answer the question."},{"who":"Speaker","line":"Now, why did it survive for so long? Wood normally rots within a few decades. The answer is the mud. The boat was buried in thick, wet clay at the bottom of the river, and that clay contained almost no oxygen. Without oxygen, the bacteria and fungi that break down wood can't survive, so the boat was preserved in remarkable condition."},{"who":"Speaker","line":"Of course, that created our biggest problem. As soon as waterlogged wood is exposed to the air, it starts to dry out, shrink and crack. So from the moment it was lifted, the boat had to be kept wet, and we sprayed it with water every few hours, day and night."},{"who":"Speaker","line":"The conservation itself took four years. First, each section of the boat was soaked in a tank containing a solution of a special wax, which gradually replaced the water inside the cells of the wood. That stage alone lasted two years. Then the sections were freeze-dried in a large chamber, which removes the last of the water without letting the wood collapse."},{"who":"Speaker","line":"Finally, the boat was put back together, and it's now displayed in a case that controls the humidity of the air around it. If the air becomes too dry or too damp, the wood could still be damaged, so sensors check it every minute."},{"who":"Speaker","line":"If you visit the gallery after the talk, you'll also see a full-size model of the complete boat, built last year by volunteers using the same methods and materials. It even floats, which I can tell you was a great relief to everyone involved. Thank you."}],"notes":{"title":"A Bronze Age boat","headings":["Discovery","The boat","How it was built","Use","Survival","Conservation","Display"],"extra":["The boat · about nine metres long","Display · a full-size working model built by volunteers"]},"groups":[{"instruction":"Questions 31-40. Complete the notes below. Write ONE WORD ONLY for each answer.","qtype":"note","questions":[{"n":31,"kind":"gap","prompt":"Discovery · found by engineers laying a ___ under the river","accept":["pipeline"],"limit":1,"evidence":"engineers were laying a new pipeline beneath the bed of the river","why":{"en":"Not years of searching: \"engineers were laying a new pipeline beneath the bed of the river\".","tr":"Yıllarca aramayla değil: \"mühendisler nehir yatağının altına yeni bir boru hattı döşüyordu\".","fa":"نه با سال‌ها جستجو: «مهندس‌ها داشتند لوله‌ی تازه‌ای زیر بستر رودخانه می‌کشیدند»."},"trap":["TR-paraphrase","TR-ruledout"]},{"n":32,"kind":"gap","prompt":"The boat · made of planks of ___","accept":["oak"],"limit":1,"evidence":"it was made of planks of oak","why":{"en":"Not one tree trunk: \"planks of oak\".","tr":"Tek bir ağaç gövdesi değil: \"meşe kalaslar\".","fa":"نه از یک تنه‌ی درخت: «تخته‌هایی از چوب بلوط»."},"trap":["TR-ruledout"]},{"n":33,"kind":"gap","prompt":"How it was built · planks sewn together with twisted ___ of yew","accept":["stems"],"limit":1,"evidence":"thin, twisted stems of yew","why":{"en":"\"Thin, twisted stems of yew\". Plural.","tr":"\"İnce, bükülmüş porsuk dalları\". Çoğul.","fa":"«ساقه‌های نازک و تابیده‌ی سرخدار». جمع."},"trap":["TR-plural"]},{"n":34,"kind":"gap","prompt":"How it was built · joints filled with ___ to keep water out","accept":["moss"],"limit":1,"evidence":"they pressed moss into the joints","why":{"en":"\"They pressed moss into the joints\" = filled the joints with moss.","tr":"\"Eklem yerlerine yosun bastırdılar\".","fa":"«خزه را در درزها فشار دادند» یعنی درزها را با خزه پر کردند."},"trap":["TR-paraphrase"]},{"n":35,"kind":"gap","prompt":"Use · seeds of ___ found inside the hull","accept":["barley"],"limit":1,"evidence":"these turned out to be barley","why":{"en":"The charred seeds \"turned out to be barley\".","tr":"Yanmış tohumların \"arpa olduğu ortaya çıktı\".","fa":"دانه‌های سوخته «معلوم شد جو هستند»."},"trap":["TR-paraphrase"]},{"n":36,"kind":"gap","prompt":"Use · one end had been deliberately ___","accept":["damaged"],"limit":1,"evidence":"It had been deliberately damaged","why":{"en":"Not rot or the river: \"It had been deliberately damaged, with tools\".","tr":"Çürüme ya da nehir değil: \"Aletlerle bilerek zarar verilmişti\".","fa":"نه پوسیدگی و نه رودخانه: «عمداً با ابزار آسیب دیده بود»."},"trap":["TR-ruledout"]},{"n":37,"kind":"gap","prompt":"Survival · the clay contained almost no ___","accept":["oxygen"],"limit":1,"evidence":"that clay contained almost no oxygen","why":{"en":"\"That clay contained almost no oxygen\", so the bacteria could not survive.","tr":"\"O kil neredeyse hiç oksijen içermiyordu\", bu yüzden bakteriler yaşayamadı.","fa":"«آن خاک رس تقریباً هیچ اکسیژنی نداشت»، پس باکتری‌ها زنده نمی‌ماندند."},"trap":["TR-paraphrase"]},{"n":38,"kind":"gap","prompt":"Conservation · soaked in a solution of ___ for two years","accept":["wax"],"limit":1,"evidence":"a solution of a special wax","why":{"en":"\"A solution of a special wax\" that replaced the water in the wood.","tr":"Ahşaptaki suyun yerini alan \"özel bir mum çözeltisi\".","fa":"«محلولی از یک موم مخصوص» که جای آب داخل چوب را گرفت."},"trap":["TR-limit"]},{"n":39,"kind":"gap","prompt":"Conservation · then ___-dried in a large chamber","accept":["freeze"],"limit":1,"evidence":"the sections were freeze-dried","why":{"en":"\"Freeze-dried\": \"-dried\" is printed, so write freeze.","tr":"\"Freeze-dried\": \"-dried\" yazılı, freeze yaz.","fa":"«freeze-dried»: «-dried» چاپ شده، پس freeze را بنویس."},"trap":["TR-limit"]},{"n":40,"kind":"gap","prompt":"Display · the case controls the ___ of the air","accept":["humidity"],"limit":1,"evidence":"controls the humidity of the air around it","why":{"en":"\"A case that controls the humidity of the air around it\".","tr":"\"Çevresindeki havanın nemini kontrol eden bir vitrin\".","fa":"«ویترینی که رطوبت هوای اطرافش را کنترل می‌کند»."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Speaker":{"accent":"Scottish","gender":"F","tts":{"engine":"piper","voice":"en_GB-alba-medium"},"role":"Museum archaeologist giving a talk"}},"sequence":[{"type":"announcer","text":"Part 4. You will hear a talk about an ancient boat found in a river. First, you have some time to look at Questions 31 to 40."},{"type":"pause","seconds":45,"note":"reading time, Questions 31-40"},{"type":"announcer","text":"Now listen carefully and answer Questions 31 to 40."},{"type":"sfx","note":"museum lecture room: slight reverb; 1.5 s pause between paragraphs"},{"type":"lines","from":0,"to":10},{"type":"announcer","text":"That is the end of Part 4. You now have two minutes to check your answers.","after":120}]},"id":"c-x09-l4-d","course":"ielts-exams","exam":"exam-09","unit":"x09-l4"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The wood was waterlogged.\" This means it was...","options":["full of water","very old","painted"],"correct":0,"why":{"en":"Waterlogged = soaked through with water.","tr":"Waterlogged = suya doymuş.","fa":"waterlogged یعنی کاملاً آب‌گرفته."}},{"tests":"paraphrase","point":3,"prompt":"Notes: \"found by ___\" (a chance discovery). Which phrase in a talk leads you to it?","options":["archaeologists searched for years","we expected to find it","it was found by accident, when"],"correct":2,"why":{"en":"\"By accident\" = by chance; the next words say who found it.","tr":"\"By accident\" = tesadüfen; sonraki kelimeler kimin bulduğunu söyler.","fa":"«by accident» یعنی تصادفی؛ کلمه‌های بعدی می‌گویند چه کسی پیدایش کرد."}},{"tests":"method","point":2,"prompt":"You hear \"Now, why did it survive for so long?\" Where are you on the notes?","options":["at the Discovery heading","at the Survival heading","at the end of the talk"],"correct":1,"why":{"en":"A question like this is a signpost to the next heading.","tr":"Böyle bir soru sonraki başlığa geçişi gösterir.","fa":"سؤالی مثل این نشانه‌ی رسیدن به عنوان بعدی است."}},{"tests":"trap","point":3,"prompt":"Notes: \"boat is ___ metres long\" (ONE WORD ONLY). Is a number possible here?","options":["No: ONE WORD ONLY never takes a figure","Yes: write 9","Yes: write nine metres"],"correct":0,"why":{"en":"With ONE WORD ONLY, a gap that needs a number will not be asked; the length is extra information.","tr":"ONE WORD ONLY’de sayı isteyen bir boşluk sorulmaz; uzunluk ek bilgidir.","fa":"در ONE WORD ONLY جای خالی‌ای که عدد بخواهد پرسیده نمی‌شود؛ طول قایق اطلاعات اضافه است."}},{"tests":"trap","point":1,"prompt":"\"It wasn’t made of pine, as we first thought. It was cedar.\" Notes: \"made of ___\". What do you write?","options":["pine","pine and cedar","cedar"],"correct":2,"why":{"en":"\"As we first thought\" marks the wrong idea; cedar is the fact.","tr":"\"İlk düşündüğümüz gibi\" yanlış fikri gösterir; sedir gerçek olan.","fa":"«آن‌طور که اول فکر کردیم» ایده‌ی غلط را نشان می‌دهد؛ سدر واقعیت است."}}],"id":"c-x09-l4-x","course":"ielts-exams","exam":"exam-09","unit":"x09-l4"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
